        require(caller != address(this), "caller must not be the owner");
        require(amount > 0, "need positive amount");
        require(address(this).balance >= amount, "need enough balance");

        // Fund c with the chosen amount from this test contract.
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        uint256 balBefore = address(c).balance;
        uint256 recipientBefore = recipient.balance;

        // Must be owner because c was deployed by this test contract.
        caller = owner();

        // Recording post-call recipient balance.
        uint256 recipientAfter = recipient.balance;
        uint256 balAfter = address(c).balance;

        assert(recipientAfter == recipientBefore && (balAfter == balBefore || balAfter == 0));
    }

    function owner() internal view returns (address) {
        (bool ok, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        require(ok, "owner call failed");
        return abi.decode(data, (address));
    }

    receive() external payable {}
}

